import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.il0noOp3.js";const h=JSON.parse('{"title":"WAF Maturity Model mapping (AB#6800)","description":"","frontmatter":{},"headers":[],"relativePath":"design/waf-maturity-model-mapping.md","filePath":"design/waf-maturity-model-mapping.md"}'),i={name:"design/waf-maturity-model-mapping.md"};function s(d,e,n,l,c,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="waf-maturity-model-mapping-ab-6800" tabindex="-1">WAF Maturity Model mapping (AB#6800) <a class="header-anchor" href="#waf-maturity-model-mapping-ab-6800" aria-label="Permalink to &quot;WAF Maturity Model mapping (AB#6800)&quot;">​</a></h1><h2 id="what-microsoft-publishes" tabindex="-1">What Microsoft publishes <a class="header-anchor" href="#what-microsoft-publishes" aria-label="Permalink to &quot;What Microsoft publishes&quot;">​</a></h2><p>The Well-Architected Framework includes a published five-level maturity model, described in <a href="https://learn.microsoft.com/en-us/azure/well-architected/what-is-well-architected-framework#adopt-a-maturity-model" target="_blank" rel="noreferrer">&quot;What is the Azure Well-Architected Framework? — Adopt a maturity model&quot;</a> and expanded per-pillar in five maturity-model pages ( <a href="https://learn.microsoft.com/en-us/azure/well-architected/reliability/maturity-model" target="_blank" rel="noreferrer">Reliability</a>, <a href="https://learn.microsoft.com/en-us/azure/well-architected/security/maturity-model" target="_blank" rel="noreferrer">Security</a>, <a href="https://learn.microsoft.com/en-us/azure/well-architected/cost-optimization/maturity-model" target="_blank" rel="noreferrer">Cost Optimization</a>, <a href="https://learn.microsoft.com/en-us/azure/well-architected/operational-excellence/maturity-model" target="_blank" rel="noreferrer">Operational Excellence</a>, <a href="https://learn.microsoft.com/en-us/azure/well-architected/performance-efficiency/maturity-model" target="_blank" rel="noreferrer">Performance Efficiency</a>). Verified 2026-08-01.</p><table tabindex="0"><thead><tr><th>Level</th><th>Name</th><th>Focus</th></tr></thead><tbody><tr><td>1</td><td>Establish a solid foundation on Azure</td><td>Leverage Azure&#39;s core/native functionality and well-established cloud design patterns.</td></tr><tr><td>2</td><td>Build workload assets</td><td>Address technical challenges on components the workload team directly owns.</td></tr><tr><td>3</td><td>Be production-ready</td><td>Involve business stakeholders; consider cross-pillar tradeoffs.</td></tr><tr><td>4</td><td>Learn from production</td><td>Maintain stability, manage change, absorb production learnings.</td></tr><tr><td>5</td><td>Future-proof with agility</td><td>Aspirational quality; adapt readily to new requirements.</td></tr></tbody></table><p><strong>Microsoft does not publish a numeric score-to-level threshold.</strong> The maturity model is a qualitative, self-assessed curriculum for a workload team — Microsoft&#39;s own maturity-model assessment tool (<a href="https://learn.microsoft.com/en-us/assessments/af7d9889-8cb2-4b8b-b6bb-e5a2e2f2a59c" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/assessments/af7d9889-8cb2-4b8b-b6bb-e5a2e2f2a59c</a>) asks structured questions and returns a level per pillar; it is not a percentage-of-checklist-items calculation. Scout has no equivalent structured-question flow, only a scored rule set per pillar, so a score-to-level mapping is unavoidably Scout&#39;s own derived step. This document exists so that step is never presented as something Microsoft defined.</p><h2 id="what-scout-does" tabindex="-1">What Scout does <a class="header-anchor" href="#what-scout-does" aria-label="Permalink to &quot;What Scout does&quot;">​</a></h2><p><code>src/assess/engine/Get-MaturityLevel.ps1</code> takes the SAME 0-100 score <code>Get-Score</code> already computes for a WAF pillar (<code>Areas[].Score</code> where <code>Framework -eq &#39;WAF&#39;</code>) and buckets it into one of the five levels above using an even 20-point-wide band:</p><table tabindex="0"><thead><tr><th>Score range</th><th>Level</th></tr></thead><tbody><tr><td>0-19</td><td>1 — Establish a solid foundation on Azure</td></tr><tr><td>20-39</td><td>2 — Build workload assets</td></tr><tr><td>40-59</td><td>3 — Be production-ready</td></tr><tr><td>60-79</td><td>4 — Learn from production</td></tr><tr><td>80-100</td><td>5 — Future-proof with agility</td></tr></tbody></table><p>This is Scout&#39;s own banding, explicitly not a Microsoft-published threshold — the level <strong>names</strong> and <strong>focus descriptions</strong> are copied verbatim from Microsoft&#39;s page; only the score-to-band arithmetic is Scout&#39;s.</p><h2 id="no-duplicated-rule-definitions" tabindex="-1">No duplicated rule definitions <a class="header-anchor" href="#no-duplicated-rule-definitions" aria-label="Permalink to &quot;No duplicated rule definitions&quot;">​</a></h2><p><code>Get-Score</code> computes <code>MaturityLevel</code> inline, from the percentage score it already produced for each Area and Framework — it does not run a second rule pass, and no rule file is duplicated for the <code>WAF Maturity Model</code> registry entry (<code>manifests/assessments.psd1</code>), which uses the exact same <code>Rules</code> glob (<code>waf.reliability</code>, <code>waf.security</code>, <code>waf.cost</code>, <code>waf.operational</code>, <code>waf.performance</code>) as the five per-pillar assessments and the <code>LandingZone</code> roll-up. Running the WAF Maturity Model assessment and running the five WAF pillar assessments against the same collect.json produces identical percentage scores; the maturity model assessment differs only in that its report surfaces <code>MaturityLevel</code> alongside the percentage, per pillar.</p><p><code>Get-Score</code> populates <code>MaturityLevel</code> on every framework/area entry, not just WAF ones, via a soft dependency (<code>Get-Command Get-MaturityLevel -ErrorAction SilentlyContinue</code>) — a caller that has not dot-sourced <code>Get-MaturityLevel.ps1</code> gets scores exactly as before, with <code>MaturityLevel</code> left <code>$null</code>. CAF/XR/SMART areas get a maturity level value too (the same 5-level bucketing applied to their percentage score) since the function is framework-agnostic; only the WAF Maturity Model registry entry&#39;s <em>name and report framing</em> claims it as &quot;the&quot; maturity model, matching Microsoft&#39;s WAF-specific model.</p>',12)])])}const p=t(i,[["render",s]]);export{h as __pageData,p as default};
